(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x + wx, sy = y + wy;
  const src1 = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*60, 0.11, 2.1]
  ];
  const src2 = [
    [200+Math.cos(t*0.7)*60, 100+Math.sin(t*0.5)*40, 0.18, 3.2],
    [300+Math.sin(t*0.6+1)*50, 150+Math.cos(t*0.8)*35, 0.22, 2.8],
    [140+Math.cos(t*0.9+2)*70, 190+Math.sin(t*0.4)*45, 0.15, 3.5],
    [380+Math.sin(t*0.55+3)*55, 80+Math.cos(t*0.75)*50, 0.2, 3.0],
    [60+Math.cos(t*0.85)*65, 220+Math.sin(t*0.65+1)*40, 0.25, 2.5]
  ];
  let aS1=0, iS1=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src1) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS1 += Math.sin(d*f - t*sp);
    iS1 += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  for (const [sX,sY,f,sp] of src2) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS2 += Math.sin(d*f - t*sp);
    iS2 += Math.sin(d*f*0.6 + t*sp*0.5 + 2.0);
  }
  const act1=aS1/7, inh1=iS1/7, act2=aS2/5, inh2=iS2/5;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
