  const spiral = (Math.sin(dist*0.05*breathe-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.03-ang*5+t*0.8)*0.5)*0.35;
  const cross = (act1*act2+inh1*inh2)*0.3;
  const r1 = Math.tanh((act1-inh1*0.7+bg*0.3+spiral)*2.2);
  const r2 = Math.tanh((act2-inh2*0.6+bg*0.2-spiral*0.5)*2.8);
  const coupled = Math.tanh((r1*0.6+r2*0.4+cross+spiral*0.3)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const grain = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*0.1;
  const blend = coupled*0.6+r1*0.15+r2*0.1+cell*0.1+grain;
  const v = blend*0.5+0.5;
  const pal = [[5,12,52],[10,45,85],[18,85,120],[25,140,135],[60,175,130],[170,195,75],[220,185,55],[215,135,65],[195,85,75],[140,50,80],[70,25,65],[25,12,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
