  const edge=Math.abs(coupled)>0.75?1.2:Math.abs(coupled)>0.5?1.08:1.0;
  const hl=Math.max(0,coupled-0.6)*0.5;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hl*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hl*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+hl*15)|0)
  ];
}
